import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';


export type ComponentNameProps = Record<string, any>;

const HandGeometry: React.FC<{ color: string; strokeColor: string; strokeWidth: number }> = ({ 
  color, 
  strokeColor, 
  strokeWidth 
}) => {
  return (
    <svg style={{ overflow: "visible" }}>
      <g stroke={strokeColor} strokeWidth={strokeWidth} strokeLinejoin="round" strokeLinecap="round">
        {/* Arm */}
        <rect x="-1200" y="-15" width="1020" height="135" fill={color} />
        {/* Palm */}
        <rect x="-200" y="-15" width="100" height="135" rx="25" fill={color} />
        {/* Pinky (folded) */}
        <rect x="-120" y="90" width="40" height="30" rx="15" fill={color} />
        {/* Ring (folded) */}
        <rect x="-120" y="55" width="50" height="30" rx="15" fill={color} />
        {/* Middle (folded) */}
        <rect x="-120" y="20" width="60" height="30" rx="15" fill={color} />
        {/* Thumb (crossing palm) */}
        <rect x="-140" y="10" width="80" height="35" rx="17.5" fill={color} transform="rotate(35, -140, 10)" />
        {/* Index Finger (extended) */}
        <rect x="-120" y="-15" width="120" height="30" rx="15" fill={color} />
      </g>
    </svg>
  );
};

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0a0a0c",
  transparentBackground = false,
  durationInSeconds = 8,
  leftHandColor = "#FFDCB6",
  rightHandColor = "#8D5524",
  strokeColor = "rgba(0,0,0,0.4)",
  strokeWidth = 3,
  approachDistance = 800,
  touchDurationPercent = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Timing Logic
  const durationFrames = durationInSeconds * fps;
  const holdFrames = Math.max(1, Math.floor(durationFrames * (touchDurationPercent / 100)));
  const moveFrames = Math.max(1, (durationFrames - holdFrames) / 2);

  const t1 = moveFrames;
  const t2 = durationFrames - moveFrames;

  // Strict monotonicity check for interpolate
  const safeT2 = t2 > t1 ? t2 : t1 + 0.1;

  // Easing interpolation for the entire journey (Approach -> Hold -> Retreat)
  const progress = interpolate(
    frame,
    [0, t1, safeT2, durationFrames],
    [0, 1, 1, 0],
    {
      easing: Easing.inOut(Easing.sin),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Calculate distance from center. 
  // We add strokeWidth / 2 so that when progress === 1, the outer stroke edges touch perfectly instead of overlapping.
  const offset = (approachDistance * (1 - progress)) + (strokeWidth / 2);

  // Responsive scale baseline
  const scale = (Math.min(width, height) / 1080) * 1.5;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      
      {/* Left Hand Container */}
      <div
        style={{
          position: "absolute",
          transform: `translate(${-offset}px, 0px) scale(${scale})`,
          transition: "none",
        }}
      >
        <HandGeometry color={leftHandColor} strokeColor={strokeColor} strokeWidth={strokeWidth} />
      </div>

      {/* Right Hand Container */}
      <div
        style={{
          position: "absolute",
          transform: `translate(${offset}px, 0px) scale(-${scale}, ${scale})`,
          transition: "none",
        }}
      >
        <HandGeometry color={rightHandColor} strokeColor={strokeColor} strokeWidth={strokeWidth} />
      </div>

    </AbsoluteFill>
  );
};

export default ComponentName;